// V8 semantic port of scripts/code_index_plan.py at bd469335; no Python or filesystem.
function req(ok,message){if(!ok)throw new Error(message);}
const STATUSES=new Set(["todo","in_progress","blocked","done","deferred"]);
const PROGRESS_START="<!-- code-index-progress:start -->",PROGRESS_END="<!-- code-index-progress:end -->";
function pyTruth(v){if(v===null||v===undefined||v===false)return false;if(typeof v==="number")return v!==0;if(typeof v==="string"||Array.isArray(v))return v.length>0;return typeof v==="object"?Object.keys(v).length>0:true;}
function get(v,k,d=null){return Object.prototype.hasOwnProperty.call(v,k)?v[k]:d;}
function counter(values){const r={};for(const v of values)r[v]=(r[v]||0)+1;return r;}
function dictEqual(a,b){return Object.keys(a).length===Object.keys(b).length&&Object.keys(a).every(k=>Object.hasOwn(b,k)&&a[k]===b[k]);}
function pyJson(v){if(v===null||typeof v!=="object")return JSON.stringify(v);if(Array.isArray(v))return "["+v.map(pyJson).join(", ")+"]";return "{"+Object.entries(v).map(([k,x])=>JSON.stringify(k)+": "+pyJson(x)).join(", ")+"}";}
function validateNavigation(data,byId){
 req(typeof data.status==="string"&&STATUSES.has(data.status),"Unknown plan status");
 if(data.status==="done"){
  req([...byId.values()].every(t=>["done","deferred"].includes(t.status)),"Done plan has unfinished tasks");
  for(const f of ["current_phase","next_task"])req(Object.hasOwn(data,f)&&data[f]===null,"Done plan requires explicit null "+f);
 }else{
  const phase=get(data,"current_phase"), nextId=get(data,"next_task"),next=typeof nextId==="string"?byId.get(nextId):null;
  req(data.phase_order.includes(phase),"Unknown current_phase");req(next!==null&&next!==undefined,"Unknown next_task");
  req(!["done","deferred"].includes(next.status),"next_task must not be done or deferred");req(next.phase===phase,"next_task does not match current_phase");
  req(next.depends_on.every(dep=>byId.get(dep).status==="done"),"next_task has unfinished hard dependency");
 }
 const recorded=get(data,"last_implementation_date"),match=typeof recorded==="string"?/^([0-9]{4})-([0-9]{2})-([0-9]{2})$/.exec(recorded):null;
 req(match!==null,"Invalid last_implementation_date; expected YYYY-MM-DD");
 const year=+match[1],month=+match[2],day=+match[3],leap=year%4===0&&(year%100!==0||year%400===0),lengths=[31,leap?29:28,31,30,31,30,31,31,30,31,30,31];
 req(year>=1&&year<=9999&&month>=1&&month<=12&&day>=1&&day<=lengths[month-1],"Invalid last_implementation_date; expected YYYY-MM-DD");
}
function validate(data,validationText){
 const tasks=data.tasks,byId=new Map(tasks.map(t=>[t.id,t]));req(byId.size===tasks.length,"Duplicate task IDs");
 const allowed=new Set(validationText.match(/(?<![\p{L}\p{N}_])V\p{Nd}{2}(?![\p{L}\p{N}_])/gu)||[]),visiting=new Set(),visited=new Set();
 function visit(key){
  req(!visiting.has(key),"Dependency cycle at "+key);if(visited.has(key))return;visiting.add(key);
  const task=byId.get(key),deps=task.depends_on.concat(get(task,"conditional_dependencies",[]).map(d=>d.task));
  for(const dep of deps){req(byId.has(dep),"Unknown dependency "+dep);visit(dep);}visiting.delete(key);visited.add(key);
 }
 for(const task of tasks){
  for(const field of ["id","phase","batch","title","scope","steps","acceptance","validations","rollback"])req(pyTruth(get(task,field)),"Missing "+field+" in "+task.id);
  req(STATUSES.has(task.status),"Unknown status in "+task.id);req(task.validations.every(v=>allowed.has(v)),"Unknown validation in "+task.id);
  if(task.status==="done"){req(pyTruth(get(task,"evidence")),"Done task lacks evidence: "+task.id);for(const dep of task.depends_on)req(byId.get(dep)?.status==="done","Done task has unfinished hard dependency: "+task.id);}
  visit(task.id);
 }
 req(data.task_count===tasks.length,"Task count drift");req(dictEqual(counter(tasks.map(t=>t.phase)),data.phase_task_counts),"Phase counts drift");
 validateNavigation(data,byId);return counter(tasks.map(t=>t.status));
}
function renderProgress(data,sourceHash,prefix){
 const tasks=data.tasks,byId=new Map(tasks.map(t=>[t.id,t])),counts=counter(tasks.map(t=>t.status));
 const states=["done","in_progress","todo","blocked","deferred"].filter(s=>(counts[s]||0)||["done","in_progress","todo"].includes(s)).map(s=>(counts[s]||0)+" "+s);
 const lines=["Code Index V2 共 **"+tasks.length+" 项任务："+states.join(" / ")+"**。",""];
 if(data.status==="done")lines.push("计划状态：\x60done\x60（本轮计划已结束）；更新日期：\x60"+data.last_implementation_date+"\x60。","所有任务均已完成或明确延期；当前阶段：无；下一任务：无。");
 else{
  const phase=data.current_phase,next=byId.get(data.next_task),focus=new Set([next.id]);
  function include(task){for(const dep of task.depends_on)if(byId.get(dep).status!=="done"&&!focus.has(dep)){focus.add(dep);include(byId.get(dep));}}
  for(const task of tasks)if(task.status==="in_progress"){focus.add(task.id);include(task);}
  lines.push("当前阶段：**"+phase+"｜"+data.phase_names[phase]+"**；计划状态：\x60"+data.status+"\x60；更新日期：\x60"+data.last_implementation_date+"\x60。",
   "下一任务：**"+next.id+"｜"+next.title+"**（硬依赖已完成）。","","| 当前下一项、进行中任务及其未完成前置 | 状态 | 硬依赖（任务状态） |","|---|---|---|");
  for(const task of tasks){
   if(!focus.has(task.id))continue;
   const dependencies=task.depends_on.map(dep=>dep+" ("+byId.get(dep).status+")").join("、")||"无";
   lines.push("| "+task.id+"｜"+task.title+" | \x60"+task.status+"\x60 | "+dependencies+" |");
  }
 }
 lines.push("","进度入口：[重构总览]("+prefix+"README.md) · [逐项 TODO]("+prefix+"05-TODO.md) · [唯一任务状态源]("+prefix+"tasks.json) · [执行交接]("+prefix+"08-HANDOFF.md)。",
 "任务完成数不等同发布认证；以各任务证据和适用验证范围为准。","","> 本块由 \x60scripts/code_index_plan.py --write\x60 从 \x60tasks.json\x60 生成；无参运行校验全部进度入口。",
 "> 源文件 SHA-256：\x60"+sourceHash+"\x60。");
 return lines.join("\n")+"\n";
}
function replaceProgress(text,progress,path){
 for(const marker of [PROGRESS_START,PROGRESS_END]){
  const escaped=marker.replace(/[.*+?^$(){}|[\]\\]/g,"\\$&");
  req(text.split(marker).length-1===1&&new RegExp("^"+escaped+"\\r?$","m").test(text),"Progress markers missing, duplicated or not standalone: "+path);
 }
 const start=text.indexOf(PROGRESS_START),end=text.indexOf(PROGRESS_END);req(start<end,"Progress markers out of order: "+path);
 return text.slice(0,start)+PROGRESS_START+"\n"+progress+PROGRESS_END+text.slice(end+PROGRESS_END.length);
}
function render(data,sourceHash){
 const tasks=data.tasks,lines=["# 05｜逐项重构 TODO（由 tasks.json 派生）","","> 任务总数："+tasks.length+"；源文件 SHA-256：\x60"+sourceHash+"\x60。",
 "> 状态只改 tasks.json；使用 scripts/code_index_plan.py --write 生成本页。","","## 总览","","| Phase | 主题 | done / 总数 |","|---|---|---:|"];
 for(const phase of data.phase_order){const subset=tasks.filter(t=>t.phase===phase);lines.push("| "+phase+" | "+data.phase_names[phase]+" | "+subset.filter(t=>t.status==="done").length+" / "+subset.length+" |");}
 for(const phase of data.phase_order){
  lines.push("","## "+phase+"｜"+data.phase_names[phase]);
  for(const t of tasks.filter(t=>t.phase===phase)){
   const checked=t.status==="done"?"x":" ";
   lines.push("","### ["+checked+"] "+t.id+"｜"+t.title,"","状态：\x60"+t.status+"\x60；批次：\x60"+t.batch+"\x60；优先级：\x60"+get(t,"priority","normal")+"\x60。",
    "范围："+t.scope.map(p=>"\x60"+p+"\x60").join("；"),"硬依赖："+(t.depends_on.join(", ")||"无"));
   for(const [key,title] of [["steps","步骤"],["deliverables","交付物"],["acceptance","验收"],["validations","验证"]])lines.push(title+"："+get(t,key,[]).join("；"));
   lines.push("回滚："+t.rollback);
   if(pyTruth(get(t,"conditional")))lines.push("条件："+t.conditional);
   if(pyTruth(get(t,"conditional_dependencies")))lines.push("条件依赖："+pyJson(t.conditional_dependencies));
   lines.push("证据："+(pyTruth(get(t,"evidence"))?pyJson(get(t,"evidence",[])):"尚无"));
   if(pyTruth(get(t,"implementation_notes")))lines.push("实施备注："+t.implementation_notes);
  }
 }
 return lines.join("\n")+"\n";
}
function generateViews(data,sourceHash,views,validationText){
 const states=validate(data,validationText),targets={"docs/roadmap/code-index-v2/05-TODO.md":render(data,sourceHash)};
 for(const [path,prefix] of [["README.md","docs/roadmap/code-index-v2/"],["docs/roadmap/code-index-v2/README.md",""],["docs/roadmap/code-index-v2/08-HANDOFF.md",""]])
  targets[path]=replaceProgress(views[path],renderProgress(data,sourceHash,prefix),path);
 return {states,targets};
}
return {validate,validateNavigation,render,renderProgress,replaceProgress,generateViews,pyJson};
